/**
 * Defines the supported message roles in a conversation.
 *
 * - user: A message sent by the customer.
 * - assistant: A response generated by the AI assistant.
 * - tool: A result returned by a backend tool.
 *
 * System instructions are generated by the backend and are not persisted.
 */
export type ConversationMessageRole = 'user' | 'assistant' | 'tool';

/**
 * Represents a function call requested by the AI model.
 *
 * The function arguments are stored as a JSON string
 * and must be validated before execution.
 */
export interface AIMessageToolCall {
  readonly id: string;
  readonly type: 'function';
  readonly function: {
    readonly name: string;
    readonly arguments: string;
  };
}

/**
 * Contains the common properties shared by all conversation messages.
 */
interface BaseConversationMessage {
  readonly id: string;
  readonly conversationId: string;
  readonly createdAt: Date;
}

/**
 * Represents a message sent by the customer.
 */
export interface UserConversationMessage extends BaseConversationMessage {
  readonly role: 'user';
  readonly content: string;
}

/**
 * Represents a response generated by the AI assistant.
 *
 * Content can be empty when the assistant only requests tool execution.
 */
export interface AssistantConversationMessage extends BaseConversationMessage {
  readonly role: 'assistant';
  readonly content: string;
  readonly toolCalls?: readonly AIMessageToolCall[];
}

/**
 * Represents the result returned by an executed backend tool.
 *
 * Every tool result must reference the corresponding tool call.
 */
export interface ToolConversationMessage extends BaseConversationMessage {
  readonly role: 'tool';
  readonly content: string;
  readonly toolCallId: string;
  readonly toolName: string;
}

/**
 * Represents any supported conversation message.
 */
export type ConversationMessage =
  | UserConversationMessage
  | AssistantConversationMessage
  | ToolConversationMessage;

/**
 * Represents one complete customer interaction.
 *
 * A turn contains the customer message, AI responses,
 * tool calls, and tool results associated with one request.
 *
 * Keeping messages grouped by turn prevents history trimming
 * from breaking tool-call and tool-result relationships.
 */
export interface ConversationTurn {
  readonly requestId: string;
  readonly sequence: number;
  readonly messages: readonly ConversationMessage[];
  readonly createdAt: Date;
}
